        if (child_pid == 0) {
            // Grandchild process lives briefly. The use-after-free occurs during its setup.
            exit(EXIT_SUCCESS);
        }
        wait(NULL);
        exit(EXIT_SUCCESS);
    }

    // --- Parent Process ---
    // 6. Wait for the child process to complete.
    wait(NULL);

    munmap(addr, 0x3000);

