/*
 * PoC for CVE-2021-3493: Linux Kernel eBPF/overlayfs Privilege Escalation
 *
 * This exploit leverages a flaw in how the overlayfs filesystem handles
 * file capabilities within user namespaces. An unprivileged user can create a
 * user namespace, mount an overlayfs, and set privileged capabilities
 * (e.g., CAP_SETUID) on an executable file in the upper directory. The kernel
 * fails to properly validate and strip these capabilities, allowing the user
 * to execute the file outside the namespace and escalate privileges to root.
 *
 * Compilation:
 *   gcc -o exploit cve-2021-3493.c
 *
 * Usage:
 *   ./exploit
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sched.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/mount.h>
#include <sys/xattr.h>
#include <fcntl.h>
#include <errno.h>

