 * Note: The actual patch refactors this logic into a helper function,
 * but the core change is the addition of the safety check shown below.
 */
static struct ucounts *__alloc_ucounts(struct user_namespace *ns, kuid_t uid,
					 struct hlist_head *hashent)
{
	// ...
	spin_unlock_irq(&ucounts_lock); /* Lock released */

	new = kzalloc(sizeof(*new), GFP_KERNEL);
	// ...
	spin_lock_irq(&ucounts_lock); /* Lock re-acquired */
	/*
	 * We dropped the lock, so now we need to check if the user namespace
	 * is still alive and if someone else allocated the ucounts.
	 */
	if (ns->ucounts == NULL) { /* PATCH: Check if namespace is still valid */
		kfree(new);
		return ERR_PTR(-ENOMEM); /* Abort if namespace is dying */
	}

	ucounts = find_ucounts(ns, uid, hashent);
	if (ucounts) {
		kfree(new);
	} else {
