    // Set pdeath_signal to SIGKILL. This should be sent to the parent
    // if the exec_id check is bypassed.
    if (prctl(PR_SET_PDEATHSIG, SIGKILL) < 0) {
        perror("prctl(PR_SET_PDEATHSIG)");
        exit(1);
    }

    // Notify the parent that setup is complete
    kill(getppid(), SIGUSR1);

    // Wait until the parent finishes its exec loop and signals us to exit
    pause(); 
    exit(0);
