    return syscall(__NR_fsopen, fs_name, flags);
}

static int fsconfig(int fs_fd, unsigned int cmd, const char *key, const void *value, int aux) {
    return syscall(__NR_fsconfig, fs_fd, cmd, key, value, aux);
