// Add an attribute to a netlink message
void add_attr(struct nlmsghdr *nlh, int maxlen, int type, const void *data, int alen) {
  int len = RTA_LENGTH(alen);
  struct rtattr *rta;

  if (NLMSG_ALIGN(nlh->nlmsg_len) + RTA_ALIGN(len) > maxlen) {
    fprintf(stderr, "add_attr: message exceeded maxlen\n");
    return;
  }

  rta = (struct rtattr*)(((char*)nlh) + NLMSG_ALIGN(nlh->nlmsg_len));
  rta->rta_type = type;
  rta->rta_len = len;
  memcpy(RTA_DATA(rta), data, alen);
  nlh->nlmsg_len = NLMSG_ALIGN(nlh->nlmsg_len) + RTA_ALIGN(len);
}

// Send a netlink message
int send_req(int sock, struct nlmsghdr *nlh) {
  struct sockaddr_nl nladdr;
  memset(&nladdr, 0, sizeof(nladdr));
  nladdr.nl_family = AF_NETLINK;

  nlh->nlmsg_seq = 0;
  nlh->nlmsg_pid = getpid();

  return sendto(sock, nlh, nlh->nlmsg_len, 0, (struct sockaddr*)&nladdr, sizeof(nladdr));
}

